def test_sequence(a):
    for p in range(len(a) - 1):
        # a_{a_{a_p}} = a_{p+1} + 1
        idx1 = a[p]
        if idx1 >= len(a): return False
        idx2 = a[idx1]
        if idx2 >= len(a): return False
        if a[idx2] != a[p+1] + 1:
            return False
    return True

# Let's try a_n = n+1 for all n.
a = [i+1 for i in range(10)]
print(f"a_n = n+1: {test_sequence(a)}")

